const upsertMetadataTable = `-- name: UpsertMetadataTable :one
INSERT INTO metadata_tables AS t (catalog_id, namespace, name, kind, fingerprint, properties, comment, last_seen_at, last_changed_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, now(), now())
ON CONFLICT (catalog_id, namespace, name) DO UPDATE
SET kind = EXCLUDED.kind,
    fingerprint = EXCLUDED.fingerprint,
    properties = EXCLUDED.properties,
    comment = EXCLUDED.comment,
    last_seen_at = now(),
    last_changed_at = CASE
        WHEN t.fingerprint IS DISTINCT FROM EXCLUDED.fingerprint OR t.removed_at IS NOT NULL THEN now()
        ELSE t.last_changed_at
    END,
    removed_at = NULL
RETURNING id, (last_changed_at = now())::boolean AS changed
`

type UpsertMetadataTableParams struct {
	CatalogID   pgtype.UUID `json:"catalog_id"`
	Namespace   []string    `json:"namespace"`
	Name        string      `json:"name"`
	Kind        string      `json:"kind"`
	Fingerprint string      `json:"fingerprint"`
	Properties  []byte      `json:"properties"`
	Comment     *string     `json:"comment"`
}

type UpsertMetadataTableRow struct {
	ID      pgtype.UUID `json:"id"`
	Changed bool        `json:"changed"`
}

// Records a table seen by the pass. changed is true when the table is new,
// came back from a tombstone or has a new fingerprint: its columns must be
// replaced.
func (q *Queries) UpsertMetadataTable(ctx context.Context, arg UpsertMetadataTableParams) (UpsertMetadataTableRow, error) {
	row := q.db.QueryRow(ctx, upsertMetadataTable,
		arg.CatalogID,
		arg.Namespace,
		arg.Name,
		arg.Kind,
		arg.Fingerprint,
		arg.Properties,
		arg.Comment,
	)
	var i UpsertMetadataTableRow
	err := row.Scan(&i.ID, &i.Changed)
	return i, err
}
